import sys

def main():
    input = sys.stdin.readline
    H, W = map(int, input().split())
    S = [input().strip() for _ in range(H)]

    min_r, max_r = H, -1
    min_c, max_c = W, -1

    for i in range(H):
        for j, ch in enumerate(S[i]):
            if ch == '#':
                min_r = min(min_r, i)
                max_r = max(max_r, i)
                min_c = min(min_c, j)
                max_c = max(max_c, j)

    for i in range(min_r, max_r + 1):
        for j in range(min_c, max_c + 1):
            if S[i][j] == '.':
                print("No")
                return

    print("Yes")

if __name__ == "__main__":
    main()
